\[
\begin{aligned}
x^{2}+y^{2} & =1 \\
\text { Left-hand side } & =\left(-\frac{\sqrt{7}}{5}\right)^{2}+\left(\frac{2}{5}\right)^{2} \\
& =\frac{7}{25}+\frac{4}{25} \\
& =\frac{11}{25} \\
\frac{11}{25} & \neq 1 \\
& \therefore \text { not on the unit circle }
\end{aligned}
\]

